mapper.insert:
insert into mall_cart (user_id, goods_id, quantity, create_time)
values (#{userId}, #{goodsId}, #{quantity}, sysdate())
on duplicate key update quantity = quantity + #{quantity}

mapper.update:
update mall_cart
set quantity = #{quantity}
where cart_id = #{cartId} and user_id = #{userId}

mapper.delete:
delete from mall_cart
where user_id = #{userId}
and cart_id in

    #{cartId}

mapper.select:
select favorite_id from mall_favorite
where user_id = #{userId} and goods_id = #{goodsId}
limit 1

select o.order_id as orderId, o.order_no as orderNo, o.user_id as userId, o.total_amount as totalAmount, o.status as status, o.remark as remark, o.create_time as createTime from mall_order o where o.user_id = #{userId}
and o.status = #{status}
order by o.create_time desc

select i.item_id as itemId, i.order_id as orderId, i.goods_id as goodsId, i.goods_name as goodsName, i.price as price, i.quantity as quantity, g.image_url as imageUrl from mall_order_item i left join mall_goods g on g.goods_id = i.goods_id where i.order_id in
#{orderId}
order by i.item_id

mapper.update:
update mall_order
set status = #{toStatus}, update_time = sysdate()
where order_id = #{orderId} and user_id = #{userId} and status = #{fromStatus}

update mall_goods
set stock = stock - #{quantity}, sales = sales + #{quantity}
where goods_id = #{goodsId} and status = '0' and del_flag = '0' and stock >= #{quantity}

update mall_goods
set stock = stock + #{quantity}, sales = sales - #{quantity}
where goods_id = #{goodsId}
